-- CheckUploads: inspects every showcase model and reports what Roblox built from it. Models with an
-- asset ID are loaded into nil (nothing is added to the place); the rest are read from
-- ServerStorage.ShowcaseImports (3D Importer / MCP imports). GENERATED by tools/roblox/gen_showcase.py.
-- Paste into the Studio command bar (edit mode). Expected per model: the textured MeshPart named
-- <Name> with a texture, Bones on fish, and a separate <Name>_Glow MeshPart where `glow` is set.

local CHECK = __CHECK__

local InsertService = game:GetService("InsertService")
local imports = game:GetService("ServerStorage"):FindFirstChild("ShowcaseImports")
local problems, missing = {}, {}
for _, c in ipairs(CHECK) do
	local ok, res = false, nil
	if c.id > 0 then
		ok, res = pcall(function()
			return InsertService:LoadAsset(c.id)
		end)
	elseif imports and imports:FindFirstChild(c.n) then
		ok, res = true, imports[c.n]:Clone()
	else
		table.insert(missing, c.n)
		continue
	end
	if not ok and c.id > 0 then
		local ok2, objs = pcall(function()
			return game:GetObjects("rbxassetid://" .. c.id)
		end)
		if ok2 and objs then
			res = Instance.new("Model")
			for _, o in ipairs(objs) do
				o.Parent = res
			end
		else
			res = nil
		end
	end
	if not res then
		table.insert(problems, c.n .. ": could not load asset " .. c.id)
		print(("%-20s %s  LOAD FAILED"):format(c.n, c.id))
	else
		local meshes, bones, glow, textured, untextured = {}, 0, false, 0, {}
		for _, d in ipairs(res:GetDescendants()) do
			if d:IsA("Bone") then
				bones += 1
			elseif d:IsA("MeshPart") then
				local tex = d.TextureID ~= "" or d:FindFirstChildOfClass("SurfaceAppearance") ~= nil
				table.insert(meshes, ("%s [%.2f x %.2f x %.2f]%s"):format(d.Name, d.Size.X, d.Size.Y, d.Size.Z, tex and " tex" or ""))
				if d.Name:lower():find("glow") then
					glow = true
				elseif tex then
					textured += 1
				else
					table.insert(untextured, d.Name)
				end
			end
		end
		print(("%-20s %s  meshparts=%d bones=%d glowpart=%s\n    %s"):format(
			c.n, c.id > 0 and c.id or "(import)", #meshes, bones, tostring(glow), table.concat(meshes, "\n    ")))
		if textured == 0 then table.insert(problems, c.n .. ": no textured MeshPart " .. table.concat(untextured, ",")) end
		if c.rigged and bones == 0 then table.insert(problems, c.n .. ": no Bones (rig lost)") end
		if c.glow and not glow then table.insert(problems, c.n .. ": no separate _Glow MeshPart") end
		res:Destroy()
	end
end
if #missing > 0 then
	warn(("[CheckUploads] %d not uploaded and not in ServerStorage.ShowcaseImports: %s"):format(#missing, table.concat(missing, ", ")))
end
if #problems == 0 then
	print(("[CheckUploads] %d checked, all OK"):format(#CHECK - #missing))
else
	warn("[CheckUploads] PROBLEMS:\n  " .. table.concat(problems, "\n  "))
end
